function objectOrNull(value) {
  if (typeof value === "string") {
    try {
      return objectOrNull(JSON.parse(value));
    } catch {
      return null;
    }
  }
  return value && typeof value === "object" && !Array.isArray(value) ? value : null;
}
function withApiWaterFrequencyValue(sourceValue, measurementValue) {
  const source = objectOrNull(sourceValue);
  if (!source) return null;
  const record2 = objectOrNull(source.record);
  if (!record2) return null;
  return { ...source, record: { ...record2, measurementValue } };
}
